import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { defineConfig, type Plugin } from "vite";

/**
 * Serve `fixtures/` to the dev and preview servers, so the validation page can
 * fetch a real `system.xml` and the GPU kernels can be compared against
 * OpenMM's own numbers in a browser.
 *
 * Local only, and deliberately: the fixtures are 0.7-7.5 MB each, are not
 * committed, and are regenerated by tools/build_reference_system.py. A
 * deployed build has no `/fixtures/` route and the page says so.
 *
 * 🔴 Registered on the **preview** server as well as the dev one, because the
 * long browser gate runs against the built page rather than the dev server --
 * see playwright.config.ts for why. A route that existed in development and
 * not in preview would make that gate fail in a way that looks like a bug in
 * the page.
 */
function serveFixtures(): Plugin {
  const root = resolve(import.meta.dirname ?? ".");
  const middleware = (
    request: { url?: string | undefined },
    response: {
      setHeader: (name: string, value: string) => void;
      end: (body?: unknown) => void;
      statusCode: number;
    },
    next: () => void,
  ): void => {
    const path = (request.url ?? "").split("?")[0] ?? "";
    // Refuse anything that could climb out of the fixtures directory.
    if (path.includes("..") || !/^\/[\w.-]+\/[\w.-]+$/.test(path)) {
      next();
      return;
    }
    try {
      const body = readFileSync(resolve(root, `fixtures${path}`));
      response.setHeader(
        "content-type",
        path.endsWith(".json") ? "application/json" : "application/xml",
      );
      response.end(body);
    } catch {
      response.statusCode = 404;
      response.end("fixture not generated; see tools/README.md");
    }
  };

  return {
    name: "mir-serve-fixtures",
    configureServer(server) {
      server.middlewares.use("/fixtures", middleware);
    },
    configurePreviewServer(server) {
      server.middlewares.use("/fixtures", middleware);
    },
  };
}

/**
 * The application is `web/`, and it imports the engine straight out of `src/`.
 * WGSL is loaded with `?raw`, so a kernel is a plain file that both the browser
 * build and the Node test lanes read the same way.
 */
export default defineConfig({
  plugins: [serveFixtures()],
  root: "web",
  // GitHub Pages serves from a repository subpath.
  base: process.env.MIR_BASE ?? "/",
  build: {
    outDir: "../dist/web",
    emptyOutDir: true,
    target: "es2023",
    assetsInlineLimit: 0,
    // Three pages, each its own entry: the landing page with the GPU and
    // precision checks, the run page, and the validation page. Vite only
    // discovers `index.html` by itself, so the other two have to be named or
    // they are silently left out of a production build.
    rollupOptions: {
      input: {
        index: resolve(import.meta.dirname ?? ".", "web/index.html"),
        run: resolve(import.meta.dirname ?? ".", "web/run.html"),
        // 🔴 Every page has to be listed here. Vite discovers only
        // index.html, so a page that is missing builds in development and is
        // silently absent from a production build -- which has happened twice.
        prepare: resolve(import.meta.dirname ?? ".", "web/prepare.html"),
        analyse: resolve(import.meta.dirname ?? ".", "web/analyse.html"),
        validate: resolve(import.meta.dirname ?? ".", "web/validate.html"),
      },
    },
  },
  server: { port: 4173, strictPort: true },
  preview: { port: 4173, strictPort: true },
  assetsInclude: ["**/*.wgsl"],
});
